"""check-phase 1: the breadth gate's parser, rules and exit codes."""

from __future__ import annotations

import hashlib
import json
import shutil
from pathlib import Path

import pytest

from vh import check_phase, cli
from vh.scaffold import PACKS, scan_repo

FIXTURE = Path(__file__).parent / "fixtures" / "scaffold" / "js_app"

HEADER = [
    "# Inputs scaffold",
    "",
    "Generated by `vh scaffold-inputs`. This is a floor, not a ceiling: recon adds what it misses.",
    "",
    "Packs: {packs}",
    "Rows: {rows}",
    "Skipped files: 0",
    "Unresolved sites: 0",
    "",
    "| # | Source Type | Location | Variable | Entry Point | Trust Hint |",
    "|---|---|---|---|---|---|",
]


def _scaffold(rows: int, packs: str = "ts") -> str:
    lines = [line.format(packs=packs, rows=rows) for line in HEADER]
    lines += [
        f"| {i} | query param | a.js:{i} | `q{i}` | <module> | http |" for i in range(1, rows + 1)
    ]
    return "\n".join(lines) + "\n"


def _inventory(cells: list[str], after: str = "") -> str:
    rows = "\n".join(
        f"| {i} | query param | a.js:{i} | {cell} | <module> | unauth |"
        for i, cell in enumerate(cells, 1)
    )
    return (
        "### Recon Output\n\n#### Input Inventory\n\n"
        f"{len(cells)} inputs across 1 entry points\n\n"
        "| # | Source Type | Location | Variable | Entry Point | Trust Level |\n"
        "|---|---|---|---|---|---|\n" + rows + "\n\n" + after
    )


def _gate(tmp_path: Path, inventory: str | None, scaffold: str | None = None) -> Path:
    results = tmp_path / "res"
    results.mkdir(parents=True)
    if inventory is not None:
        (results / "phase1_output.md").write_text(inventory)
    if scaffold is not None:
        (results / "inputs_scaffold.md").write_text(scaffold)
    return results


def test_good_inventory_passes(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    results = _gate(tmp_path, _inventory(["`a`", "`b`"]), _scaffold(2))
    assert cli.main(["check-phase", "1", str(results)]) == 0
    assert capsys.readouterr().out.splitlines()[-1] == "inputs: scaffold 2 / inventoried 2"


@pytest.mark.parametrize("cell", ["`a`, `b`", "`a` `b`", "`a` plus", "`a b`", "`a,b`", "plain"])
def test_grouped_cell_fails(tmp_path: Path, cell: str) -> None:
    findings, summary = check_phase.check(
        _gate(tmp_path, _inventory([cell]), _scaffold(1)), tmp_path / "res" / "inputs_scaffold.md"
    )
    assert "P1-GROUPED-ROW" in {finding.rule for finding in findings}
    assert summary["passed"] is False


def test_na_variable_passes(tmp_path: Path) -> None:
    findings, summary = check_phase.check(
        _gate(tmp_path, _inventory(["`N/A`"]), _scaffold(1)),
        tmp_path / "res" / "inputs_scaffold.md",
    )
    assert findings == []
    assert summary["passed"] is True


def test_thin_fails(tmp_path: Path) -> None:
    findings, summary = check_phase.check(
        _gate(tmp_path, _inventory(["`a`"]), _scaffold(2)),
        tmp_path / "res" / "inputs_scaffold.md",
    )
    thin = [finding for finding in findings if finding.rule == "P1-THIN"]
    assert len(thin) == 1
    assert "1" in thin[0].message and "2" in thin[0].message
    assert summary["passed"] is False


@pytest.mark.parametrize(
    ("packs", "warning"), [("ts", "P1-EMPTY-SCAFFOLD"), ("none", "P1-NO-PACK")]
)
def test_empty_scaffold_and_no_pack_warn(tmp_path: Path, packs: str, warning: str) -> None:
    findings, summary = check_phase.check(
        _gate(tmp_path, _inventory(["`a`, `b`"]), _scaffold(0, packs)),
        tmp_path / "res" / "inputs_scaffold.md",
    )
    rules = {finding.rule for finding in findings}
    assert warning in rules
    assert "P1-THIN" not in rules
    assert "P1-GROUPED-ROW" in rules
    assert summary["passed"] is False


@pytest.mark.parametrize("case", ["no-output", "no-inventory", "no-scaffold", "bad-scaffold"])
def test_missing_artifacts(tmp_path: Path, case: str) -> None:
    expected = {
        "no-output": "P1-NO-OUTPUT",
        "no-inventory": "P1-NO-INVENTORY",
        "no-scaffold": "P1-NO-SCAFFOLD",
        "bad-scaffold": "P1-NO-SCAFFOLD",
    }[case]
    if case == "no-output":
        results = _gate(tmp_path, None, _scaffold(1))
    elif case == "no-inventory":
        results = _gate(tmp_path, "### Recon Output\n\n#### Input Inventory\n", _scaffold(1))
    elif case == "bad-scaffold":
        results = _gate(tmp_path, _inventory(["`a`"]), "# Inputs scaffold\n\nhello\n")
    else:
        results = _gate(tmp_path, _inventory(["`a`"]), None)
    findings, _ = check_phase.check(results, results / "inputs_scaffold.md")
    assert expected in {finding.rule for finding in findings}


