def test_section_bounds_match_template(tmp_path: Path) -> None:
    inventory = (
        "### Recon Output\n\nProduce a compact Attack Surface Report\n\n"
        "#### Input Inventory\n\n2 inputs across 2 entry points\n\n"
        "| # | Source Type | Location | Variable | Entry Point | Trust Level |\n"
        "|---|---|---|---|---|---|\n"
        "| 1 | query param | a.js:1 | `q` | <module> | unauth |\n"
        "| 2 | query param | a.js:2 | `r` | <module> | unauth |\n\n"
        "##### Extra notes\n\n"
        "| # | Source Type | Location | Variable | Entry Point | Trust Level |\n"
        "|---|---|---|---|---|---|\n"
        "| 3 | body field | b.js:1 | `s` | <module> | unauth |\n\n"
        "#### Threat Model\n\n"
        "| Entry-point group | App-layer auth enforcement | Caller identity binding |\n"
        "|---|---|---|\n| x | y | z |\n\n"
        "#### Subgraph Partitions\n\n"
        "| Partition | Inputs |\n|---|---|\n| sg-1 | q |\n"
    )
    findings, summary = check_phase.check(
        _gate(tmp_path, inventory, _scaffold(3)), tmp_path / "res" / "inputs_scaffold.md"
    )
    assert findings == []
    assert summary["inventory_rows"] == 3


def test_scaffold_round_trip(tmp_path: Path) -> None:
    out = tmp_path / "inputs_scaffold.md"
    assert cli.main(["scaffold-inputs", str(FIXTURE), "--out", str(out)]) == 0
    packs, count = check_phase._scaffold(out)
    assert packs == "ts"
    assert count == len(scan_repo(FIXTURE, PACKS).rows)


